CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(10) NOT NULL CHECK (role IN ('ADMIN','STAFF')), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE suppliers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE, contact_person VARCHAR(100), email VARCHAR(150), phone VARCHAR(30), address VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description VARCHAR(1000), category_id BIGINT NOT NULL REFERENCES categories(id), supplier_id BIGINT REFERENCES suppliers(id), unit_price DECIMAL(14,2) DEFAULT 0 NOT NULL CHECK (unit_price>=0), quantity BIGINT DEFAULT 0 NOT NULL CHECK (quantity>=0), reorder_level BIGINT DEFAULT 10 NOT NULL CHECK (reorder_level>=0), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE stock_movements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), user_id BIGINT NOT NULL REFERENCES users(id), movement_type VARCHAR(3) NOT NULL CHECK (movement_type IN ('IN','OUT')), quantity BIGINT NOT NULL CHECK (quantity>0), reason VARCHAR(500), balance_after BIGINT NOT NULL CHECK (balance_after>=0), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX idx_movements_created_at ON stock_movements(created_at);
CREATE INDEX idx_movements_product ON stock_movements(product_id);
